-lock-timeout <s>  Seconds to wait for the full-build lock (0 = forever).\\n  --status            Report the planned action and exit without changing anything.\\n  -h | --help         Show this text.\\n\\nEnvironment: MIPSTARRE_CACHE_ROOT, MIPSTARRE_FULL_BUILD_LOCK_TIMEOUT,\\nMIPSTARRE_TELEMETRY_DIR.\\nMIPSTARRE_LAKE_ROOT optionally relocates this worktree's `.lake` directory.\\nEOF\\n}\\n\\niso_now()   { date +%Y-%m-%dT%H:%M:%S%z; }\\nepoch_now() { date +%s; }\\nstamp_id()  { date -u +%Y%m%dT%H%M%SZ; }\\n\\n# Ported from .githooks/pre-push: clear Git's per-invocation environment before\\n# invoking Lake or nested git operations, or an outer hook's GIT_DIR leaks into\\n# the vendored package checkouts and they resolve the wrong repository.\\nrun_outside_git_env() (\\n  if command -v git >/dev/null 2>&1; then\\n    for name in $(git rev-parse --local-env-vars); do\\n      unset \\\"$name\\\" || true\\n    done\\n  fi\\n  \\\"$@\\\"\\n)\\n\\nsha256_stdin() {\\n  if command -v shasum >/dev/null 2>&1; then\\n    shasum -a 256 | awk '{print $1}'\\n  elif command -v sha256sum >/dev/null 2>&1; then\\n    sha256sum | awk '{print $1}'\\n  else\\n    die \\\"no sha256 tool found (need shasum or sha256sum)\\\"\\n  fi\\n}\\n\\n\",\"exit_code\":0,\"status\":\"completed\"}}\n273:{\"type\":\"item.started\",\"item\":{\"id\":\"item_133\",\"type\":\"command_execution\",\"command\":\"/bin/bash -lc \\\"python3 -c 'import json; from pathlib import Path; wanted={\\\\\\\"prover-258-20260906-01\\\\\\\",\\\\\\\"prover-259-20260906-01\\\\\\\",\\\\\\\"prover-261-20260906-01\\\\\\\",\\\\\\\"scout-123-nonencoding-mass-20260906-01\\\\\\\",\\\\\\\"scout-123-nonencoding-mass-20260906-02\\\\\\\"}; rows=[json.loads(s) for s in Path(\\\\\\\"results/telemetry/sessions.jsonl\\\\\\\").read_text().splitlines() if s.strip()]; print(json.dumps([{k:r.get(k) for k in [\\\\\\\"name\\\\\\\",\\\\\\\"status\\\\\\\",\\\\\\\"wall_s\\\\\\\",\\\\\\\"usage\\\\\\\",\\\\\\\"usage_scope\\\\\\\",\\\\\\\"observed_usage\\\